          permVoid: perms.void ?? null,
          permReassign: perms.reassign ?? null,
          permClose: perms.close ?? null,
          permReopen: perms.reopen ?? null,
          graceDays,
          entryDate,
          graceA: gradeGraces.A ?? null,
          graceB: gradeGraces.B ?? null,
          graceC: gradeGraces.C ?? null,
