      this.latePctInput.set(null);
      this.policyInput.set(null);
      this.numberingInput.set(null);
      this.capInput.set(null);
      this.thresholdInput.set(null);
      this.noteThresholdInput.set(null);
      this.permInput.set({});
      this.graceInput.set(null);
